import{_ as i,r as o,o as n,c as s,e as r,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Preparing for Production - October CMS User Guide","titleTemplate":false,"description":"Understand your project structure and configure your site for a live environment","frontmatter":{"subtitle":"Understand your project structure and configure your site for a live environment"},"headers":[{"level":2,"title":"Know Your Project","slug":"know-your-project","link":"#know-your-project","children":[]},{"level":2,"title":"Configure the Environment","slug":"configure-the-environment","link":"#configure-the-environment","children":[{"level":3,"title":"Disable Debug Mode","slug":"disable-debug-mode","link":"#disable-debug-mode","children":[]},{"level":3,"title":"Set Your Application URL","slug":"set-your-application-url","link":"#set-your-application-url","children":[]},{"level":3,"title":"Verify Your Application Key","slug":"verify-your-application-key","link":"#verify-your-application-key","children":[]},{"level":3,"title":"Configure Your Database","slug":"configure-your-database","link":"#configure-your-database","children":[]}]},{"level":2,"title":"Configure Nginx","slug":"configure-nginx","link":"#configure-nginx","children":[]},{"level":2,"title":"File Permissions","slug":"file-permissions","link":"#file-permissions","children":[]},{"level":2,"title":"Optimize for Performance","slug":"optimize-for-performance","link":"#optimize-for-performance","children":[]},{"level":2,"title":"Pre-Deployment Checklist","slug":"pre-deployment-checklist","link":"#pre-deployment-checklist","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/deployment/preparing-for-production.md","filePath":"user-guide/quickstart/deployment/preparing-for-production.md"}'),d={name:"user-guide/quickstart/deployment/preparing-for-production.md"};function p(u,e,h,g,f,m){const t=o("pre-heading"),a=o("post-heading");return n(),s("div",null,[r(t),e[0]||(e[0]=l("h1",null,"Preparing for Production",-1)),r(a),e[1]||(e[1]=c(`<p>Your site works locally. Now let&#39;s get it ready for the real world. Before deploying, it helps to understand which parts of your project actually matter and what settings to change for production.</p><h2 id="know-your-project"><a href="#know-your-project" class="header-anchor">#</a> Know Your Project</h2><p>An October CMS project contains many directories, but your site really lives in just three:</p><ul><li><strong><code>app/</code></strong>: your application code, custom classes, and app-level blueprints</li><li><strong><code>plugins/</code></strong>: installed plugins and any custom plugins you build</li><li><strong><code>themes/</code></strong>: your theme files (layouts, pages, partials, blueprints, assets)</li></ul><p>Everything you have built in this tutorial (the theme, the blueprints, the pages) lives in <code>themes/</code>. If you installed any plugins, they are in <code>plugins/</code>. These three directories are what make your site yours.</p><p>The other directories (<code>modules/</code>, <code>vendor/</code>) are framework code provided by Composer. They are excluded from version control by default because they can be rebuilt with <code>composer install</code> at any time.</p><h2 id="configure-the-environment"><a href="#configure-the-environment" class="header-anchor">#</a> Configure the Environment</h2><p>Most production settings live in your <code>.env</code> file in the project root. Here are the important ones to change:</p><h3 id="disable-debug-mode"><a href="#disable-debug-mode" class="header-anchor">#</a> Disable Debug Mode</h3><p>Debug mode shows detailed error messages during development. In production, those messages expose sensitive information.</p><div class="language- extra-class"><pre class="language-text"><code>APP_DEBUG=false
</code></pre></div><p>With debug mode off, visitors see a clean error page while detailed errors go to your log files.</p><h3 id="set-your-application-url"><a href="#set-your-application-url" class="header-anchor">#</a> Set Your Application URL</h3><div class="language- extra-class"><pre class="language-text"><code>APP_URL=https://www.yoursite.com
</code></pre></div><p>Make sure this matches your actual domain with <code>https://</code>.</p><h3 id="verify-your-application-key"><a href="#verify-your-application-key" class="header-anchor">#</a> Verify Your Application Key</h3><p>The <code>APP_KEY</code> is used for encryption. It is generated during installation, but confirm it exists:</p><div class="language- extra-class"><pre class="language-text"><code>APP_KEY=base64:xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
</code></pre></div><p>If it is missing, generate one:</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan key:generate
</code></pre></div><h3 id="configure-your-database"><a href="#configure-your-database" class="header-anchor">#</a> Configure Your Database</h3><p>Update with your production database credentials:</p><div class="language- extra-class"><pre class="language-text"><code>DB_CONNECTION=mysql
DB_HOST=127.0.0.1
DB_PORT=3306
DB_DATABASE=your_production_database
DB_USERNAME=your_database_user
DB_PASSWORD=your_database_password
</code></pre></div><h2 id="configure-nginx"><a href="#configure-nginx" class="header-anchor">#</a> Configure Nginx</h2><p>If your server uses Nginx, October CMS includes a ready-made configuration file at <code>nginx.conf</code> in the project root. Copy or reference this file in your Nginx server block to ensure URL rewriting and other settings work correctly.</p><div class="custom-block tip"><p>Apache users do not need to worry about this. October CMS includes an <code>.htaccess</code> file that handles URL rewriting automatically.</p></div><h2 id="file-permissions"><a href="#file-permissions" class="header-anchor">#</a> File Permissions</h2><p>Your web server needs write access to these directories:</p><ul><li><code>storage/</code> (and all subdirectories)</li><li><code>bootstrap/cache/</code></li></ul><p>On most Linux servers:</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">chmod</span> <span class="token parameter variable">-R</span> <span class="token number">755</span> storage bootstrap/cache
<span class="token function">chown</span> <span class="token parameter variable">-R</span> www-data:www-data storage bootstrap/cache
</code></pre></div><p>The exact user (<code>www-data</code>) depends on your server setup.</p><h2 id="optimize-for-performance"><a href="#optimize-for-performance" class="header-anchor">#</a> Optimize for Performance</h2><p>Once your settings are configured, cache them for faster performance:</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:optimize
</code></pre></div><h2 id="pre-deployment-checklist"><a href="#pre-deployment-checklist" class="header-anchor">#</a> Pre-Deployment Checklist</h2><div class="custom-block tip"><p>Quick summary of everything on this page:</p><ul><li>[ ] <code>APP_DEBUG</code> set to <code>false</code></li><li>[ ] <code>APP_URL</code> set to your live domain</li><li>[ ] <code>APP_KEY</code> is present</li><li>[ ] Database credentials set for production</li><li>[ ] Nginx configured (if applicable)</li><li>[ ] <code>storage/</code> and <code>bootstrap/cache/</code> are writable</li><li>[ ] <code>php artisan october:optimize</code> has been run</li></ul></div><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>With your configuration in place, head to <a href="./deploying-your-site.html">Deploying Your Site</a> for instructions on getting your project onto a live server.</p><p>For the full reference on configuration options, see <a href="./../../../4.x/setup/configuration.html">Configuration</a> and <a href="./../../../4.x/setup/deployment.html">Deployment</a> in the developer documentation.</p>`,40))])}const v=i(d,[["render",p]]);export{x as __pageData,v as default};
